-- then guides
insert into guides (id, content) values ('e36-o2-sensors', '{"id": "e36-o2-sensors", "title": "Oxygen (O2) sensors", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same NGK/Bosch sensor and 22 mm hex on any M52/S52 E36 (328i with the dual-cat midsection also has four)", "category": "Engine", "kind": "repair", "heroId": "e36-o2-hero", "heroCap": "Four sensors on the M3''s dual exhaust: two pre-cat (upstream) screwed into the header collectors, two post-cat (downstream) after each catalytic converter. Same part in all four holes.", "glance": {"timeFirst": "1–1.5 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$140–740 for four", "risk": "Seized sensors in old steel · a rounded hex if you use the wrong tool", "why": "The M3''s dual exhaust means four O2 sensors, not two. As they age they read lean, the DME adds fuel to compensate, and the rich mixture kills fuel economy and eventually cooks the cats — and an M3 midsection is a four-figure part. BMW''s interval is 100k. It''s a screw-out, screw-in job; the only enemy is corrosion.", "note": "Same Genuine part (11781427884) fits all four positions. Cheaper NGK/Bosch equivalents are the same sensor without the roundel."}, "lifespan": {"title": "When to expect it", "headline": ["BMW interval is 100,000 miles for all four", "A single lazy sensor can trip a code well before that"], "earliest": "Any time after a misfire, oil-burning episode, or leaded/track fuel", "detail": "Sensors drift lean as the platinum element ages. A drifting pre-cat sensor makes the DME run rich (bad economy, sooty plugs, cat damage); a post-cat sensor mostly just monitors the cat, so a bad one throws a code without changing how the car runs. Replace all four together at 100k or chase them individually by code.", "factors": ["Mileage", "Oil consumption or coolant in the exhaust (poisons the element)", "Silicone sealants near the intake (silicon poisons sensors)"], "inspect": ["Scan for pending codes; a slow-switching pre-cat sensor shows before it sets a hard code", "Fuel economy trending down with no other cause"], "confidence": {"level": "high", "n": 3, "note": "Interval and failure mode agree across Doug''s Domain, Pelican and BMW''s own schedule."}}, "should": {"yesIf": ["Check-engine light with an O2 / catalyst-efficiency code", "Fuel economy dropping, plugs sooty, faint rich smell", "You''re at or past 100k and don''t know their age", "You''re doing an exhaust or header job and they''re right there"], "codes": ["P0130", "P0136", "P0150", "P0156", "P0420", "P0430"], "notes": ["Two pre-cat (before the cats, in the collectors) and two post-cat (after each cat). All four are the same part number here.", "A code names a bank and a position (upstream/downstream) — replace that one, or do all four if you''re past 100k.", "Anti-seize on the threads only if the sensor doesn''t come pre-coated (most do). Keep it off the sensor tip.", "No coding needed. Clear the code after; if it was a hard fault the light goes out after a few drive cycles."], "confidence": {"level": "high", "n": 4, "note": "Position layout and ''same part'' confirmed at three vendors."}}, "variants": {"question": "Which sensor is the code pointing at?", "hint": "A scan tool names the bank and whether it''s upstream (pre-cat, affects how the car runs) or downstream (post-cat, monitors the cat). No code and past 100k? Do all four.", "options": [{"id": "pre", "label": "Pre-cat (upstream)", "when": "P0130/P0150, rich running, economy loss. Screwed into the header collector."}, {"id": "post", "label": "Post-cat (downstream)", "when": "P0136/P0156, P0420/P0430. After the cat; easier to reach."}, {"id": "all", "label": "All four", "when": "100k service, or you''re under there anyway."}]}, "parts": [{"tier": "oe", "name": "O2 sensor — Genuine BMW", "pn": "11781427884", "note": "Same part all four positions. Plug-and-play, no splicing", "price": "$185 ea", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Exhaust/O2-Sensors/Genuine-BMW-Oxygen-Sensor-11781427884.html"}]}, {"tier": "oem", "name": "O2 sensor — NGK or Bosch", "pn": "NGK 24304 · Bosch equivalent", "note": "Same sensor, maker''s box. The value pick", "price": "$35–60 ea", "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/BMW-E36-M3-S52_3.2l/Engine/Emissions/Oxygen_Sensor/"}]}, {"tier": "oe", "name": "Anti-seize (if not pre-coated)", "pn": "nickel or copper", "note": "Threads only, never the tip", "price": "$6", "links": []}], "aftermarket": [], "tools": [{"name": "22 mm (7/8\") O2 sensor socket — the slotted kind that passes the wire, or an offset O2 wrench"}, {"name": "For the pre-cat pair: access from below. 16 mm for the aluminium skid/reinforcement plate bolts, 8 mm for the rear cover screws if fitted"}, {"name": "Torque wrench to ~50 Nm; penetrating oil; jack and stands"}, {"name": "A scan tool to read and clear the code"}], "before": ["Warm the exhaust slightly then let it cool to just-warm — a warm sensor threads out easier, a hot one burns you.", "Trace which connector goes to which sensor before you unplug; the pre-cat plugs live up near the intake, the post-cat ones under the car.", "Penetrating oil on the threads an hour ahead if the car has never had these out."], "steps": [{"n": 1, "title": "Find the code, find the sensor", "blocks": [{"t": "text", "b": "Scan the car. The code tells you bank (1 = cylinders 1–3, 2 = 4–6) and position (sensor 1 = pre-cat, sensor 2 = post-cat). Match that to the four physical sensors: two in the header collectors, two after the cats."}, {"t": "ill", "id": "e36-o2-hero", "cap": "Four positions on the dual system. Upstream sensors run rich when they fail; downstream ones just flag the cat."}]}, {"n": 2, "title": "Reach the pre-cat pair", "only": ["pre", "all"], "blocks": [{"t": "text", "b": "Front up on stands. Drop the aluminium reinforcement/skid plate (five 16 mm bolts) and any rear cover (8 mm) for room. The two upstream sensors screw into the collectors just below the manifolds — tight, hot real estate. Follow each lead up to its connector near the intake and unplug before you wrench, so you''re not twisting the wire."}]}, {"n": 3, "title": "Reach the post-cat pair", "only": ["post", "all"], "blocks": [{"t": "text", "b": "These sit after each cat, lower and in the open — the easy two. Unplug at the connector, then get the socket on the hex."}]}, {"n": 4, "title": "Out with the old", "blocks": [{"t": "text", "b": "22 mm slotted socket over the sensor, feeding the wire through the slot; breaker bar if it''s seized (penetrating oil, patience — you do not want to strip a hex in a header). It should crack loose then spin out by hand."}, {"t": "warn", "b": "If a pre-cat sensor is truly welded in and starts to round, stop. A rounded sensor in a $1,000+ header is a machine-shop problem; heat and a proper offset wrench beat forcing it."}]}, {"n": 5, "title": "In with the new", "blocks": [{"t": "text", "b": "Anti-seize on the threads if the new one isn''t pre-coated — a dab, threads only, nothing on the sensor tip. Start it by hand to be sure it''s not cross-threading into the bung, then snug with the socket."}, {"t": "torque", "label": "O2 sensor into bung", "nm": 45, "c": {"level": "community", "n": 3, "note": "Bosch/NGK spec is ~40–50 Nm; most owners go ''firm by feel'' since a torque wrench rarely fits. 45 Nm if you can."}}, {"t": "text", "b": "Route the lead exactly as the old one ran — away from the exhaust, no tension — and click the connector home."}]}, {"n": 6, "title": "Button up and clear", "blocks": [{"t": "text", "b": "Reinstall the reinforcement plate and covers, lower the car. Clear the code with the scan tool. If it was a hard fault it may take a few drive cycles for the readiness monitors to reset — that''s normal before an emissions test."}]}], "alsoReplace": [{"name": "The other three sensors", "why": "Same age, same job, all four exposed once you''re under there. Cheap insurance against a cooked cat.", "only": ["pre", "post"]}, {"name": "Reinforcement plate bolts", "why": "If they''re rusty, new ones are pennies and you''re removing them anyway.", "only": ["pre", "all"]}], "check": {"tab": "Which sensor?", "title": "Reading the code", "illId": "e36-o2-hero", "illCap": "Bank and position map to a physical sensor.", "rows": [{"see": "P0130 / P0150", "means": "Pre-cat (sensor 1), bank 1 / bank 2.", "do": "Upstream sensor, that bank."}, {"see": "P0136 / P0156", "means": "Post-cat (sensor 2), bank 1 / bank 2.", "do": "Downstream sensor, that bank."}, {"see": "P0420 / P0430", "means": "Catalyst below threshold — often a tired post-cat sensor, sometimes a dying cat.", "do": "Post-cat sensor first; test the cat if it returns."}, {"see": "Rich running, sooty plugs, no code yet", "means": "A pre-cat sensor drifting lean.", "do": "Live data: a slow-switching upstream sensor."}, {"see": "Code returns right after clearing", "means": "Wiring or connector, not the sensor.", "do": "Check the plug and lead for melt/chafe."}], "c": {"level": "high", "n": 3, "note": "Standard OBD2 bank/sensor mapping."}}, "aftercare": ["Watch fuel economy recover over the next few tanks.", "If you cleared for an emissions test, drive a full cycle so the monitors set to ''ready''."], "disagreements": [{"topic": "Genuine vs NGK/Bosch", "pos": "Some insist on Genuine; others run NGK for a third of the price.", "call": "NGK/Bosch is the same sensor. Buy Genuine only if you want the box."}, {"topic": "Anti-seize or not", "pos": "Some sensors ship pre-coated and say don''t add more.", "call": "Follow the box. If bare threads, a thin nickel anti-seize, tip kept clean."}], "sources": ["Doug''s Domain (dvatp.com) — DIY Oxygen Sensor Replacement (four-sensor layout, why it matters, cat cost)", "Pelican Parts / Bimmerfest — O2 socket size (22 mm, slotted), pre vs post access", "BimmerWorld and ECS listings — Genuine 11781427884 and NGK/Bosch equivalents, all-position fitment"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-position-sensors', '{"id": "e36-position-sensors", "title": "Crank & cam position sensors", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same two sensors on any M52/S52 E36; note the cam sensor moved from the front of the head to the rear on later cars", "category": "Engine", "kind": "repair", "heroId": "e36-pos-hero", "heroCap": "Two Hall-effect sensors: the crank sensor low on the front of the block above the crank pulley, reading the flywheel/reluctor; the cam sensor at the front (early) or rear (late) of the head, reading the intake cam.", "glance": {"timeFirst": "30–60 min", "timeRepeat": "20 min", "difficulty": 2, "cost": "$60–160", "risk": "A no-start if you ignore a crank-sensor warning · a brittle old connector", "why": "The crank sensor tells the DME where the engine is; lose it and the car won''t start or dies while driving. The cam sensor refines timing and, if it fails, gives a rough idle and poor economy — rarely a no-start on its own. The crank sensor was a known BMW failure with a recall (SI on the M52 sensor), so check whether yours was ever replaced free before you buy one.", "note": "Both are one-bolt Hall-effect sensors. The only complication is the cam sensor''s location changed mid-production and can hide behind the oil filter housing."}, "lifespan": {"title": "When to expect it", "headline": ["No fixed interval — they fail from heat and vibration", "Crank sensor: a known weak point, subject of a BMW recall/SI"], "earliest": "Any mileage; heat-soak failures show as a hot restart problem", "detail": "The crank sensor sits near the block and cooks over time; classic symptom is a car that won''t restart hot, then fires once cool. The cam sensor drifts and throws a code with a lumpy idle. A crank-sensor fault can strand you; a cam-sensor fault usually just runs rough.", "factors": ["Heat cycling", "Oil contamination on the tip", "An aftermarket crank sensor that isn''t up to the original spec (a common repeat-failure complaint)"], "inspect": ["Won''t restart when hot, fires when cool → crank sensor", "Rough idle 600–2,000 rpm with a cam-sensor code → cam sensor"], "confidence": {"level": "high", "n": 3, "note": "Symptoms and the crank-sensor recall confirmed at Pelican and the E36 blog recall thread."}}, "should": {"yesIf": ["No-start or stalls while driving, especially when hot (crank)", "Rough idle, hesitation, poor economy with a cam-sensor code", "P0335 / P0336 (crank) or P0340 (cam)", "You''ve never checked whether the crank-sensor recall was done"], "codes": ["P0335", "P0336", "P0340"], "notes": ["Crank sensor: front of the block, above the crank pulley, one 5 mm hex or E-Torx bolt. Follow the lead to its connector.", "Cam sensor: front of the head on early cars (easy); on later cars it''s at the rear near the starter, and reaching the connector is easiest with the oil filter housing off — do it during an oil change (FCP''s tip).", "Test before buying: crank sensor reads roughly 500–600 ohms; a wildly different reading (open or megohms) is a bad sensor. But a good ohm reading doesn''t rule out a heat-soak fault.", "No coding. Clear the code after."], "confidence": {"level": "high", "n": 3, "note": "Locations and test values from Pelican and owner threads."}}, "variants": {"question": "Which sensor?", "hint": "Crank = no-start / stall, front of the block. Cam = rough running, front or rear of the head depending on year.", "options": [{"id": "crank", "label": "Crankshaft sensor", "when": "P0335/P0336, no-start or hot-stall. Front of the block."}, {"id": "cam", "label": "Camshaft sensor", "when": "P0340, rough idle. Front (early) or rear (late) of the head."}]}, "parts": [{"tier": "oe", "name": "Crankshaft position sensor — Genuine/OEM", "pn": "12141703277", "note": "Confirm against your VIN on RealOEM — a few revisions exist", "price": "$45–90", "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/BMW-E36-M3-S52_3.2L/Engine/Electrical/Sensors/Crankshaft_Position/"}], "only": ["crank"]}, {"tier": "oe", "name": "Camshaft position sensor — Genuine/OEM", "pn": "12141703221", "note": "Same sensor family; some use it for both positions", "price": "$60–100", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Engine/Engine-Sensors/M52-S52-Camshaft-Reference-Sensor-OEM-12141703221.html"}], "only": ["cam"]}, {"tier": "oe", "name": "Connector repair kit (if the plug is brittle)", "pn": "housing + terminals + seals", "note": "Cheap insurance on a 25-year-old connector", "price": "$15", "links": []}, {"tier": "oe", "name": "O-ring for the sensor", "pn": "in most sensor kits", "note": "Light oil on it going in", "price": "$3", "links": []}], "aftermarket": [], "tools": [{"name": "5 mm hex or E-Torx (E5/E6) for the sensor bolt — check yours"}, {"name": "Multimeter to test resistance before buying"}, {"name": "Jack and stands for the crank sensor; the cam sensor may want the oil filter housing off"}, {"name": "Scan tool to read and clear"}], "before": ["Engine cold enough to touch, and off.", "Note the routing of the sensor lead and how the connector clips before you unplug — the plastic is old and brittle.", "If you''re testing first, have the resistance figure handy (~550 ohms for the crank sensor)."], "steps": [{"n": 1, "title": "Confirm it''s the sensor", "blocks": [{"t": "text", "b": "Scan for the code. If you can, back it up with a resistance check at the connector — a crank sensor around 500–600 ohms is healthy, open or megohms is dead. Remember a heat-soak failure can pass a cold ohm test, so trust the symptom (hot no-start) too."}, {"t": "ill", "id": "e36-pos-hero", "cap": "Crank sensor low on the front of the block; cam sensor front or rear of the head by year."}]}, {"n": 2, "title": "Crank sensor: out and in", "only": ["crank"], "blocks": [{"t": "text", "b": "Front up on stands. The sensor is on the front of the block above the crank pulley, near the starter side. Follow its lead to the connector and unplug (squeeze the clip). One bolt — 5 mm hex or E-Torx. Pull the sensor straight out; it''s just an O-ring in a bore."}, {"t": "text", "b": "Light oil on the new O-ring, seat it fully, one bolt, plug in. Route the lead exactly as before, clear of the belt and pulley."}, {"t": "torque", "label": "Crank sensor bolt (M6)", "nm": 10, "c": {"level": "community", "n": 2, "note": "M6 into aluminium; 10 Nm is the general E36 M6 figure. Snug, don''t crank it."}}]}, {"n": 3, "title": "Cam sensor: find it first", "only": ["cam"], "blocks": [{"t": "text", "b": "Early cars: front of the head, same area as an M50 — easy, one bolt, unplug and swap. Later cars: it''s at the rear of the head near the starter, and the connector is buried under the intake. FCP''s trick is to do it during an oil change with the oil filter housing off, which opens up the connector access below the intake without pulling the manifold. Big hands may still need the intake off."}, {"t": "text", "b": "One bolt (5 mm hex / E-Torx), pull the sensor, oil the new O-ring, seat, bolt, plug in."}, {"t": "torque", "label": "Cam sensor bolt (M6)", "nm": 10, "c": {"level": "community", "n": 2, "note": "As the crank sensor: M6 into aluminium, ~10 Nm."}}]}, {"n": 4, "title": "Clear and test", "blocks": [{"t": "text", "b": "Lower the car, clear the code, start it. A crank-sensor fix should turn a no-start into a start; a cam-sensor fix should smooth the idle. If the code comes straight back, suspect the connector or wiring, not a second new sensor."}, {"t": "warn", "b": "If a fresh crank sensor still no-starts, don''t just buy another — several owners chased a broken signal wire or a bad connector for hundreds of miles. Check the lead and the DME feed."}]}], "alsoReplace": [{"name": "The connector", "why": "The 25-year-old plug is often the real fault. A repair kit is $15 and saves a repeat job."}, {"name": "Oil & filter", "why": "The oil filter housing is off for the late cam sensor — do the oil change in the same session.", "only": ["cam"]}], "check": {"tab": "Which sensor?", "title": "Crank or cam?", "illId": "e36-pos-hero", "illCap": "Two sensors, two very different symptoms.", "rows": [{"see": "Won''t start, or dies driving; worse when hot", "means": "Crank sensor.", "do": "Front of the block. Test ~550 ohms."}, {"see": "Rough idle, hesitation, P0340", "means": "Cam sensor.", "do": "Front (early) or rear (late) of the head."}, {"see": "New crank sensor, still no-start", "means": "Signal wire or connector.", "do": "Check the lead and DME feed, not another sensor."}, {"see": "Both crank & cam codes at once", "means": "Often a cam sensor or shared wiring, not two dead sensors.", "do": "Cam sensor and its connector first."}, {"see": "Ran fine, then died after work near the VANOS", "means": "A crank-sensor lead knocked or broken during that job.", "do": "Inspect the lead you were near."}], "c": {"level": "high", "n": 3, "note": "Symptom split from Pelican threads and the recall history."}}, "aftercare": ["Confirm a hot restart after the crank sensor — drive it to temp, shut off, restart.", "Watch for the code returning over a few cycles."], "disagreements": [{"topic": "OEM vs cheap aftermarket crank sensor", "pos": "Autozone-grade sensors sometimes fail again fast.", "call": "Use Genuine/OEM here. Owner threads are full of repeat failures on bargain crank sensors."}, {"topic": "Recall", "pos": "Many M52 cars had the crank sensor replaced free under an old SI.", "call": "Check your history first — you may not need to buy one, or it may already be the updated part."}], "sources": ["Pelican Parts — E36 Crankshaft and Camshaft Position Sensor articles (locations, resistance, no-start diagnosis)", "FCP Euro blog — cam sensor replacement on an E36 328i (do it with the oil filter housing off)", "BMW E36 blog — M52 crank sensor recall/SI thread", "ECS / BimmerWorld listings — sensor part numbers and fitment"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-oil-pan-gasket', '{"id": "e36-oil-pan-gasket", "title": "Oil pan gasket", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same lower-pan-and-subframe layout on any six-cylinder E36; the M3 shares the pan gasket 11131437237", "category": "Engine", "kind": "repair", "heroId": "e36-pan-hero", "heroCap": "The oil pan bolts to the bottom of the block. The front subframe crosses right under it, so the pan can''t drop far enough to clear until the subframe is lowered a few inches.", "glance": {"timeFirst": "5–7 hr", "timeRepeat": "3–4 hr", "difficulty": 4, "cost": "$60–150 in parts", "risk": "The subframe is in the way · power-steering lines take the weight if you''re careless · an alignment after", "why": "The pan gasket weeps with age and drips onto the subframe and exhaust — the classic ''why is there always a spot under the front'' leak. The pan itself is easy; the catch is the subframe crosses under it, so you support the engine from above, drop the subframe a few inches, and only then can the pan come out. Do it once, do it right — cutting the gasket to sneak it in without dropping the subframe is how you end up doing it twice.", "note": "Torques are Bentley/TIS M6 and M8 values. The subframe-drop method is the consensus across every E36/E46 write-up; the no-drop method exists but you can''t torque the pan bolts properly, which is the whole point."}, "lifespan": {"title": "When to expect it", "headline": ["Weeps at 120,000–180,000 miles or with age as the gasket hardens", "Often found while doing engine or trans mounts"], "earliest": "Sooner if the car sat, or if a previous pan job used RTV instead of the gasket", "detail": "The cork-composite gasket shrinks and the pan''s many M6 bolts relax, so oil seeps at the seam. It''s a slow drip, not a gush — but it lands on the subframe, the steering rack and the exhaust, and it never gets better. Because the subframe has to come down anyway, most people do the front engine mounts and the oil filter housing gasket in the same session.", "factors": ["Age and heat cycling of the gasket", "A prior RTV-only ''repair''", "Over- or under-torqued pan bolts from a past job"], "inspect": ["A film of oil on top of the front subframe and the back of the sump", "Drips that show up after the car sits, front-centre"], "confidence": {"level": "community", "n": 3, "note": "Interval is owner consensus; failure mode agrees across E36/E46 threads."}}, "should": {"yesIf": ["Oil seeping at the pan-to-block seam, film on the subframe", "A persistent front-centre drip that isn''t the filter housing or the front main seal", "You''re already dropping the subframe for mounts or a rack", "A previous RTV bodge is weeping again"], "codes": [], "notes": ["This needs an engine support brace (from above) and enough room to drop the subframe a few inches — a lift or good stands and a lot of floor time.", "Genuine pan gasket 11131437237. Do NOT cut it to fit without dropping the subframe; a cut gasket is a future leak.", "The subframe (with the steering rack and PS pump on it) is heavy — support it on a jack and sling it so the power-steering lines never take the load.", "Some subframe and reinforcement-plate bolts are stretch (single-use). Have replacements on hand and expect an alignment after."], "confidence": {"level": "high", "n": 4, "note": "Method and cautions consistent across Pelican, e36-tech and E46 write-ups."}}, "parts": [{"tier": "oe", "name": "Oil pan gasket — Genuine", "pn": "11131437237", "note": "One-piece; fit it whole, don''t cut it", "price": "$25–45", "links": []}, {"tier": "oe", "name": "Oil pan bolts (as needed)", "pn": "M6 × various", "note": "Replace any that are stretched or rusty", "price": "$1 ea", "links": []}, {"tier": "oe", "name": "Subframe / reinforcement-plate stretch bolts", "pn": "per RealOEM for your VIN", "note": "Single-use where specified — don''t reuse", "price": "$30–50 set", "links": []}, {"tier": "oe", "name": "Drain plug crush washer", "pn": "07119963300", "note": "New every drain", "price": "$1", "links": []}, {"tier": "oem", "name": "RTV for the four gasket corners only", "pn": "Reinzosil / Three Bond", "note": "A dab where the pan meets the timing cover and rear main carrier, not a bead all round", "price": "$12", "links": []}, {"tier": "oe", "name": "Front engine mounts (while you''re there)", "pn": "per VIN", "note": "Subframe''s down — the mounts are right there", "price": "$40–90", "links": []}, {"tier": "oe", "name": "Engine oil + filter", "pn": "see the oil-change guide", "note": "It''s all coming out anyway", "price": "$40–60", "links": []}], "aftermarket": [{"name": "Engine support brace (Harbor Freight or similar)", "note": "Bar across the strut towers to hold the engine while the subframe drops. ~$70 and reusable for mounts and clutch work.", "price": "$70", "signal": "Required", "links": []}], "tools": [{"name": "Engine support brace (from above)"}, {"name": "E-Torx set for the pan bolts, 10 mm and 13 mm sockets, 16–18 mm for subframe/mount hardware, breaker bar"}, {"name": "Torque wrench 8–110 Nm; jack for the subframe plus a sling/rope to suspend it"}, {"name": "Big drain pan, gasket scraper / plastic razor, brake cleaner, rags"}, {"name": "Ramps or four stands and a lot of clearance, or a lift"}], "before": ["Drain the oil first, cold-ish so it''s not scalding but flows. New crush washer for the plug.", "Photograph the subframe bolt positions and any shims; some are locating and go back exactly.", "Set up the support brace and take the engine''s weight BEFORE you unbolt a single mount or subframe bolt.", "Have the stretch bolts and an alignment appointment lined up — this job disturbs the front geometry."], "steps": [{"n": 1, "title": "Drain, lift, support the engine", "blocks": [{"t": "text", "b": "Oil out, plug back with a new washer. Front up high on stands or a lift — you need room for the subframe to come down. Rig the engine support brace across the strut towers and lift the engine just enough to take its weight off the mounts."}]}, {"n": 2, "title": "Reinforcement plate and mounts", "blocks": [{"t": "text", "b": "Remove the aluminium reinforcement plate under the front of the car. Unbolt the bottom of each engine mount from the subframe. This is the moment to plan the front mounts as a replacement — they''re now exposed and $40–90."}]}, {"n": 3, "title": "Drop the subframe a few inches", "blocks": [{"t": "text", "b": "Support the subframe on a jack. Remove the four subframe-to-chassis bolts (big — 16–18 mm, may be stretch bolts). Lower the subframe slowly a few inches — just enough to clear the pan. You may need to free the sway bar, end links or lower control arm bushings for the last bit of travel."}, {"t": "warn", "b": "The subframe carries the steering rack and power-steering pump and is heavy. Sling it from the body or engine so the PS lines never bear its weight — a stretched line is a new leak and a bleed."}, {"t": "ill", "id": "e36-pan-hero", "cap": "Engine held from above, subframe lowered on a jack: now the pan has room to drop and rotate out."}]}, {"n": 4, "title": "Pan off", "blocks": [{"t": "text", "b": "Remove all the pan bolts (E-Torx / 10 mm), keeping them in order — lengths vary. Tap around the pan with a rubber mallet to break the sealant; it won''t just fall. Work it down and rotate it out through the gap between block and subframe. Watch the oil pickup tube as it clears."}, {"t": "note", "b": "Now''s the moment for the oil filter housing gasket and the front mounts if you''re doing them — everything down here is accessible for the only time in years."}]}, {"n": 5, "title": "Clean both faces", "blocks": [{"t": "text", "b": "Scrape every trace of old gasket and sealant off the pan lip and the block face — plastic razor and brake cleaner, until both are bright and dry. Any old material left behind is a fresh leak. Check the pan isn''t warped at the bolt holes from a past over-torque; flatten a lip if needed."}]}, {"n": 6, "title": "New gasket, pan up", "blocks": [{"t": "text", "b": "Lay the one-piece gasket on the pan dry — no full RTV bead. A small dab of RTV only in the four corners where the pan meets the timing cover and the rear main carrier (that''s where they leak). Lift the pan into place, start every bolt by hand so nothing cross-threads, then snug them."}, {"t": "warn", "b": "Do not cut the gasket to ''help'' it fit. A cut gasket is why the subframe is down at all — do it whole and torque it properly."}, {"t": "text", "b": "Torque in a spiral from the centre out, in two passes. M6 pan bolts to 10 Nm; any M8 to 22 Nm. Even, gentle — the pan is thin and warps if you crank one corner."}, {"t": "torque", "label": "Oil pan bolts (M6, 8.8)", "nm": 10, "c": {"level": "high", "n": 4, "note": "Bentley/TIS M6 8.8 = 10 Nm; 10.9 = 12 Nm. Confirmed across multiple E36/E46 torque sheets."}}, {"t": "torque", "label": "Oil pan bolts (M8, 8.8)", "nm": 22, "c": {"level": "high", "n": 3, "note": "M8 8.8 = 22 Nm, same sources."}}]}, {"n": 7, "title": "Subframe back up", "blocks": [{"t": "text", "b": "Raise the subframe back to the body, new stretch bolts where specified, and torque them — this is the step everyone says is fiddly, lining the holes back up. Reconnect the engine mounts, sway bar and anything you freed. Reinforcement plate on."}, {"t": "torque", "label": "Subframe-to-body bolts", "nm": 110, "c": {"level": "community", "n": 2, "note": "Owner references put the M12 subframe bolts around 100–110 Nm; verify against a torque sheet for your exact bolt — several are stretch and some sources add an angle stage."}}]}, {"n": 8, "title": "Fill, run, check, align", "blocks": [{"t": "text", "b": "Lower the car, engine mounts torqued, fresh oil and filter in. Run it, check the pan seam and the drain plug for leaks, then re-check cold after the first drive."}, {"t": "warn", "b": "The front geometry was disturbed — get an alignment. Dropping and re-seating the subframe moves camber and toe even if you lined it up carefully."}]}], "alsoReplace": [{"name": "Oil filter housing gasket", "why": "Another common front leak, right here with the pan down. Do both and you''ve fixed the two usual front-oil-leak sources at once."}, {"name": "Front engine mounts", "why": "Subframe''s down and the mount bottoms are unbolted. The one time they''re easy."}, {"name": "Oil pump pickup / nut safety-wire", "why": "With the pan off the pump is exposed; some owners safety-wire the pump nut (a known S-engine failure). Optional but this is the access."}, {"name": "Subframe/reinforcement stretch bolts", "why": "Single-use where specified — new ones go back."}], "check": {"tab": "Is it the pan?", "title": "Where''s the oil coming from?", "illId": "e36-pan-hero", "illCap": "Front oil leaks stack up in the same place — narrow it before you drop the subframe.", "rows": [{"see": "Film on top of the front subframe, wet pan seam", "means": "Pan gasket.", "do": "This guide."}, {"see": "Oil higher up, around the filter canister", "means": "Oil filter housing gasket.", "do": "Cheaper, no subframe — do it first, or both together."}, {"see": "Drip right behind the crank pulley", "means": "Front main seal.", "do": "Different job; check before committing to the pan."}, {"see": "Wet only after hard driving", "means": "Overfill or a breather, not the pan.", "do": "Check level and PCV first."}, {"see": "Leak returns after a pan job", "means": "Cut gasket, RTV-only, or bad torque last time.", "do": "Do it properly with a whole gasket."}], "c": {"level": "high", "n": 3, "note": "Leak-source ladder from Pelican and E36/E46 write-ups."}}, "aftercare": ["Cold level and leak check after each of the first few drives.", "Get the alignment done before you put real miles on it.", "Re-look at the pan seam at 500 miles."], "disagreements": [{"topic": "Drop the subframe or not", "pos": "Some remove the bolts without dropping the subframe and RTV or cut the gasket.", "call": "Drop it. You can''t torque the pan bolts properly otherwise, and that''s the whole point — every experienced write-up says so."}, {"topic": "Gasket or all-RTV", "pos": "A few skip the gasket and use only RTV.", "call": "Gasket, with RTV only in the four corners. All-RTV works until it doesn''t."}, {"topic": "Reuse subframe bolts?", "pos": "Some reuse them; BMW calls several single-use.", "call": "Replace the stretch bolts. They''re cheap next to a subframe."}], "sources": ["Pelican Parts — E30/E36 Oil Pan Gasket Replacement (procedure, the subframe problem)", "e36-tech.com — Ultimate Subframe/Oil Pan/Timing Case Service guide (part numbers incl. gasket 11131437237, sequence)", "E46 Fanatics DIY threads — subframe drop, engine support, stretch bolts, alignment after (same layout)", "Bentley/TIS via community torque sheets — M6 10 Nm, M8 22 Nm oil pan values"], "embeds": []}'::jsonb);

